/**
 * Derived business details. Do NOT edit this file for a new client —
 * edit src/client.config.ts instead.
 */
import { client } from '../client.config'

const areas = client.serviceAreas.filter(Boolean)

function joinList(items: string[]) {
  if (items.length <= 1) return items.join('')
  return `${items.slice(0, -1).join(', ')} and ${items.at(-1)}`
}

const tokens: Record<string, string> = {
  name: client.business.name,
  city: client.location.city,
  state: client.location.state,
  discom: client.discom || 'your DISCOM',
  areas: joinList(areas.length ? areas : [client.location.city]),
  areas2: (areas.length ? areas : [client.location.city])
    .slice(0, 2)
    .join(', '),
}

/** Replaces {name}, {city}, {state}, {discom}, {areas}, {areas2} in copy. */
export function t(text: string) {
  return text.replace(/\{(\w+)\}/g, (m, key: string) => tokens[key] ?? m)
}

/** '9000000000' → '+91 90000 00000' */
function formatPhone(digits: string) {
  const d = digits.replace(/\D/g, '').slice(-10)
  return d.length === 10 ? `+91 ${d.slice(0, 5)} ${d.slice(5)}` : digits
}

const phoneDigits = client.contact.phone.replace(/\D/g, '').slice(-10)
const waDigits = (client.contact.whatsapp || client.contact.phone)
  .replace(/\D/g, '')
  .slice(-10)

export const site = {
  id: client.id,
  name: client.business.name,
  description: t(client.copy.metaDescription),
  metaTitle: t(client.copy.metaTitle),
  url: (client.business.url || import.meta.env.VITE_SITE_URL || '').replace(
    /\/$/,
    '',
  ),
  location: client.location,
  serviceAreas: areas,
  discom: tokens.discom,
  contact: {
    phoneDisplay: formatPhone(phoneDigits),
    phoneHref: `tel:+91${phoneDigits}`,
    whatsappNumber: `91${waDigits}`,
    whatsappMessage: t(client.contact.whatsappMessage),
    email: client.contact.email,
    hours: client.contact.hours,
  },
  credentials: client.credentials,
  brand: client.brand,
  images: client.images,
  tracking: client.tracking,
}

export function whatsappLink(message = site.contact.whatsappMessage) {
  return `https://wa.me/${site.contact.whatsappNumber}?text=${encodeURIComponent(message)}`
}

/**
 * Where leads are delivered. Netlify Forms is primary (the form only shows
 * success if it accepts the lead). Google Sheets is best-effort and switches
 * itself on when GOOGLE_SHEETS_WEBHOOK_URL is set in Netlify — no code change.
 */
export const leadDestinations: Array<'netlify-forms' | 'google-sheets'> = [
  'netlify-forms',
  'google-sheets',
]

export const leadForm = {
  name: 'solar-lead',
  endpoint: '/__forms.html',
}
